(x, y, t) => {
  const cx = 240, cy = 120;
  const wx = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10 + Math.sin((x+y)*0.008+t*0.15)*20;
  const wy = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10 + Math.cos((x-y)*0.01-t*0.18)*18;
  const wx2 = Math.sin(wx*0.03+t*0.5)*8 + Math.cos(wy*0.025-t*0.4)*6;
  const wy2 = Math.cos(wx*0.025-t*0.45)*8 + Math.sin(wy*0.03+t*0.55)*6;
  const sx = x+wx+wx2, sy = y+wy+wy2;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.85],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.1],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.9],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.05],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.95],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+1)*50, 0.11, 2.1, 0.8],
    [400+Math.cos(t*0.55+2)*60, 200+Math.sin(t*0.75+4)*55, 0.13, 1.8, 1.15]
  ];
  let aS=0, iS=0, mS=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const wave = Math.sin(d*f - t*sp);
    aS += wave * w;
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5) * w;
    mS += Math.sin(d*f*1.3 - t*sp*1.4 + 2.8) * w * 0.4;
  }
  const tw = 8;
  const act = aS/tw, inh = iS/tw, mod = mS/tw;
  const bg1 = Math.sin(sx*0.04+sy*0.025+t*0.8);
  const bg2 = Math.sin(sx*0.03-sy*0.04+t*1.1);
  const bg3 = Math.sin((sx+sy)*0.12+t*2.5)*0.2;
  const bg4 = Math.sin((sx-sy)*0.1-t*2)*0.2;
  const bg5 = Math.sin(sx*0.08+t*1.8)*Math.sin(sy*0.06-t*1.3)*0.3;
  const bg = (bg1+bg2)/2 + bg3 + bg4 + bg5;
  const dist = Math.sqrt((sx-cx)**2+(sy-cy)**2);
  const ang = Math.atan2(sy-cy, sx-cx);
  const sp1 = Math.sin(dist*0.05-ang*3-t*1.5);
  const sp2 = Math.sin(dist*0.04+ang*4-t*1.2);
  const sp3 = Math.sin(dist*0.07-ang*2+t*0.9)*0.3;
  const spiral = (sp1+sp2)*0.4 + sp3;
  const turb = Math.sin(sx*0.2+sy*0.15+t*3)*Math.cos(sx*0.15-sy*0.2-t*2.5)*0.15;
  const diff = act - inh*0.7 + bg*0.3 + spiral + mod*0.5 + turb;
  const reaction = Math.tanh(diff*2.2);
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const ridge = Math.abs(Math.sin(dist*0.03-ang*5+t*0.8))*0.15;
  const blend = reaction*0.6 + cell*0.2 + ridge*0.2;
  const v = blend*0.5+0.5;
  const pal = [
    [5,10,45],[12,40,85],[18,75,120],[25,125,130],
    [60,170,140],[140,195,110],[210,190,65],
    [220,145,55],[195,95,65],[160,50,70],
    [110,25,65],[60,15,55],[25,10,48],[5,10,45]
  ];
  const idx = v*(pal.length-1);
  const i = Math.min(idx|0, pal.length-2);
  const f = idx-i;
  const lum = 0.85+Math.sin(reaction*Math.PI)*0.15;
  const edge = Math.abs(reaction)>0.75 ? 1.12 : Math.abs(reaction)>0.5 ? 1.05 : 1.0;
  const glow = Math.max(0, 1-Math.abs(reaction))*0.15;
  return [
    Math.min(255, ((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge + glow*80)|0),
    Math.min(255, ((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge + glow*120)|0),
    Math.min(255, ((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge + glow*180)|0)
  ];
}
